const cache = new Map();                        // key -> { value, expiresAt, inflight }
async function getOrLoad(key, load) {
  const hit = cache.get(key);
  if (hit && hit.expiresAt > Date.now()) return hit.value;
  if (hit?.inflight) return hit.inflight;       // share one load across concurrent misses
  const inflight = load()
    .then(v => { cache.set(key, { value: v, expiresAt: Date.now() + TTL }); return v; })
    .catch(e => { cache.delete(key); throw e; });   // never cache a rejected promise
  cache.set(key, { expiresAt: 0, inflight });
  return inflight;
}
